export default function LearnlyLogin(props: LearnlyLoginProps) {
  const app = props.app;
  const reduce = useReducedMotion();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const auth = app ? app.auth : null;
  const signup = !!auth && auth.mode === "signup";
  const providers = auth && Array.isArray(auth.providers) ? auth.providers : [];
  const canSignUp = !!auth && !!auth.canSignUp;

  const submit = async () => {
    if (!auth || busy) return;
    setBusy(true); setErr(null);
    try {
      if (signup) await auth.signUp({ email, password, name });
      else await auth.signIn(email, password);
    } catch (e) { setErr(e instanceof Error ? e.message : "Hmm, that didn't work. Check your details."); }
    setBusy(false);
  };

  const social = async (p: string) => {
    if (!auth) return;
    setErr(null);
    try { await auth.startProvider(p); } catch (e) { setErr(e instanceof Error ? e.message : "Couldn't start that sign-in. Try again."); }
  };

