import React, { useEffect, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion, animate } from "motion/react";
import { GraduationCap, LogOut, Plus, Users, Trophy, Target, Book, X, AlertTriangle, Check } from "lucide-react";

type R = Record<string, any>;
const COV: Record<string, { u: string; e: string; a: string; b: string }> = {
  Art: { u: "1513364776144-60967b0f800f", e: "🎨", a: "#FF7A59", b: "#FFB020" }, Code: { u: "1555066931-4365d14bab8c", e: "💻", a: "#8E6CF0", b: "#3FA7FF" },
  Cooking: { u: "1509440159596-0249088772ff", e: "🍞", a: "#FFB020", b: "#FF7A59" }, Photo: { u: "1516035069371-29a1b244cc32", e: "📸", a: "#3FA7FF", b: "#8E6CF0" },
  Languages: { u: "1543783207-ec64e4d95325", e: "🗣️", a: "#1FBF9A", b: "#3FA7FF" }, Finance: { u: "1579621970563-ebec7560ff3e", e: "💰", a: "#1FBF9A", b: "#FFB020" },
  Design: { u: "1561070791-2526d30994b5", e: "✏️", a: "#8E6CF0", b: "#FF7A59" }, Lifestyle: { u: "1485955900006-10f4d324d411", e: "🪴", a: "#1FBF9A", b: "#FFB020" },
};
function Cover({ c, className }: { c: R; className?: string }) {
  const [bad, setBad] = useState(false);
  const k = COV[String(c.category)] || COV.Art;
  if (bad) return <div className={(className || "") + " grid place-items-center text-6xl"} style={{ background: "linear-gradient(135deg," + k.a + "," + k.b + ")" }}>{k.e}</div>;
  return <img src={"https://images.unsplash.com/photo-" + k.u + "?auto=format&fit=crop&w=900&q=70"} alt={String(c.title)} className={className} onError={() => setBad(true)} />;
}
function Av({ s, cls }: { s: R | undefined; cls: string }) {
  const n = String(s ? s.name : "?");
  const hue = [C.coral, C.grape, C.mint, C.sky, C.sun][n.length % 5];
  return <span className={cls + " grid shrink-0 place-items-center rounded-full font-extrabold text-white"} style={{ background: hue }}>{n.split(" ").map((w) => w[0]).slice(0, 2).join("")}</span>;
}
const C = { bg: "#FFF7E6", ink: "#2A1F4D", mute: "#7B7197", sun: "#FFB020", coral: "#FF7A59", mint: "#1FBF9A", sky: "#3FA7FF", grape: "#8E6CF0" };
const TINT: Record<string, string> = { Art: C.coral, Code: C.grape, Cooking: C.sun, Photo: C.sky, Languages: C.mint, Finance: C.mint, Design: C.grape, Lifestyle: C.mint };
const FONT = "'Baloo 2','Nunito',ui-rounded,'SF Pro Rounded',system-ui,sans-serif";
const SHADOW = "0 1px 2px rgba(42,31,77,.06), 0 8px 24px -8px rgba(42,31,77,.14), 0 24px 48px -24px rgba(42,31,77,.12)";

function useCount(to: number) {
  const [v, setV] = useState(0);
  const reduce = useReducedMotion();
  useEffect(() => {
    if (reduce) { setV(to); return; }
    const a = animate(0, to, { duration: 1, ease: "easeOut", onUpdate: (x) => setV(Math.round(x)) });
    return () => a.stop();
  }, [to, reduce]);
  return v;
}

function Stat({ I, label, value, suffix, color }: { I: React.ComponentType<{ size?: number; color?: string }>; label: string; value: number; suffix?: string; color: string }) {
  const n = useCount(value);
  return (
    <div className="rounded-[26px] bg-white p-4" style={{ boxShadow: SHADOW }}>
      <span className="grid h-10 w-10 place-items-center rounded-2xl" style={{ background: color + "2E" }}><I size={20} color={color} /></span>
      <p className="mt-3 text-4xl font-extrabold leading-none">{n}{suffix}</p>
      <p className="mt-1 text-sm font-bold" style={{ color: C.mute }}>{label}</p>
    </div>
  );
}

export type InstructorHomeProps = { app?: AppHandle };

export default function InstructorHome({ app }: InstructorHomeProps) {
  const reduce = useReducedMotion();
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [summary, setSummary] = useState("");
  const [category, setCategory] = useState("Art");
  const [level, setLevel] = useState("beginner");
  const [cover, setCover] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const courses = ((app ? app.rows("course") : []) as R[]);
  const meId = app ? app.me("instructor") : undefined;
  const mine = courses.filter((c) => c.instructor_id === meId);
  const me = ((app ? app.rows("instructor") : []) as R[]).find((i) => i.id === meId);
  const enrolls = (app ? app.rows("enrollment") : []) as R[];
  const attempts = (app ? app.rows("quiz_attempt") : []) as R[];
  const students = (app ? app.rows("student") : []) as R[];
  const lessons = (app ? app.rows("lesson") : []) as R[];
  const covers = Array.from(new Set(courses.map((c) => String(c.cover)))).slice(0, 8);
  const passRate = attempts.length ? Math.round((attempts.filter((a) => a.result === "passed").length / attempts.length) * 100) : 0;
  const uniqueStudents = new Set(enrolls.map((e) => e.student_id)).size;
  const completions = enrolls.filter((e) => e.status === "completed").length;
  const alerts = attempts.filter((a) => a.result === "failed").slice(0, 4);
  const cats = ["Art", "Code", "Cooking", "Photo", "Languages", "Finance", "Design", "Lifestyle"];
  const stag = (i: number) => ({ initial: { opacity: 0, y: reduce ? 0 : 22 }, animate: { opacity: 1, y: 0 }, transition: { delay: reduce ? 0 : 0.06 * i, type: "spring" as const, stiffness: 260, damping: 24 } });
  if (!app) return null;

  const create = async () => {
    if (!title.trim() || !summary.trim()) { setErr("Give your course a title and a short summary."); return; }
    setBusy(true); setErr(null);
    try {
      const row = await app.create("course", { title: title.trim(), summary: summary.trim(), category, level, cover: cover || covers[0] || "", instructor_id: meId });
      setOpen(false); setTitle(""); setSummary("");
      app.navigate("/teach/" + String((row as R).id));
    } catch (e) { setErr(e instanceof Error ? e.message : "Could not create the course."); }
    setBusy(false);
  };

  const input = "w-full rounded-2xl border-2 bg-white px-4 py-3 text-base font-bold outline-none focus:border-[#FFB020]";

  return (
    <div className="min-h-screen w-full overflow-x-hidden pb-16" style={{ background: C.bg, color: C.ink, fontFamily: FONT }}>
      <style>{"@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;700;800&family=Nunito:wght@500;700;800&display=swap');"}</style>
      <header className="sticky top-0 z-20 px-4 py-3 backdrop-blur" style={{ background: "rgba(255,247,230,.9)" }}>
        <div className="mx-auto flex max-w-6xl items-center gap-3">
          <div className="grid h-10 w-10 place-items-center rounded-2xl" style={{ background: C.sun, boxShadow: "0 4px 0 #E8940A" }}><GraduationCap size={22} /></div>
          <span className="text-2xl font-extrabold">Learnly</span>
          <span className="rounded-full px-3 py-1 text-xs font-extrabold" style={{ background: "rgba(142,108,240,.16)", color: C.grape }}>Instructor</span>
          <button onClick={() => app.auth.signOut()} className="ml-auto flex items-center gap-2 rounded-full bg-white px-4 py-2 text-sm font-extrabold" style={{ boxShadow: SHADOW }}><LogOut size={16} />Sign out</button>
        </div>
      </header>

      <div className="mx-auto max-w-6xl px-4 pt-4 lg:pt-8">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            {me && <Av s={me} cls="h-14 w-14 text-xl" />}
            <div>
              <motion.p {...stag(0)} className="text-sm font-bold" style={{ color: C.mute }}>Your teaching studio</motion.p>
              <motion.h1 {...stag(1)} className="text-4xl font-extrabold leading-none lg:text-5xl">Hi {me ? String(me.name).split(" ")[0] : "there"}! 🌻</motion.h1>
            </div>
          </div>
          <motion.button {...stag(2)} whileHover={{ scale: 1.04 }} whileTap={{ scale: 0.94 }} onClick={() => setOpen(true)} className="flex items-center gap-2 rounded-full px-6 py-3 text-lg font-extrabold" style={{ background: C.sun, boxShadow: "0 6px 0 #E8940A" }}><Plus size={20} strokeWidth={3} />New course</motion.button>
        </div>

        <div className="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-4 lg:gap-5">
          <Stat I={Book} label="Courses" value={mine.length} color={C.sun} />
          <Stat I={Users} label="Students" value={uniqueStudents} color={C.sky} />
          <Stat I={Trophy} label="Completions" value={completions} color={C.mint} />
          <Stat I={Target} label="Quiz pass rate" value={passRate} suffix="%" color={C.grape} />
        </div>

        <div className="mt-8 grid gap-6 lg:grid-cols-[1fr_320px]">
          <div>
            <h2 className="text-2xl font-extrabold">My courses</h2>
            {mine.length === 0 ? (
              <div className="mt-3 rounded-[32px] bg-white p-10 text-center" style={{ boxShadow: SHADOW }}>
                <div className="text-6xl">📚</div><p className="mt-2 text-2xl font-extrabold">Create your first course</p>
                <p className="font-bold" style={{ color: C.mute }}>Add lessons and quizzes, then watch students grow.</p>
              </div>
            ) : (
              <div className="mt-3 grid grid-cols-1 gap-5 md:grid-cols-2">
                {mine.map((c, i) => {
                  const es = enrolls.filter((e) => e.course_id === c.id);
                  const done = es.filter((e) => e.status === "completed").length;
                  const n = lessons.filter((l) => l.course_id === c.id).length;
                  const at = attempts.filter((a) => a.course_id === c.id);
                  const avg = at.length ? Math.round((at.reduce((s, a) => s + (Number(a.score) / Math.max(1, Number(a.total))), 0) / at.length) * 100) : 0;
                  const color = TINT[String(c.category)] || C.sun;
                  return (
                    <motion.div key={c.id} {...stag(i + 3)} whileHover={{ y: -6 }} whileTap={{ scale: 0.97 }} role="button" tabIndex={0} onClick={() => app.navigate("/teach/" + c.id)} onKeyDown={(ev) => { if (ev.key === "Enter") app.navigate("/teach/" + c.id); }} className="group cursor-pointer overflow-hidden rounded-[28px] bg-white" style={{ boxShadow: SHADOW }}>
                      <div className="relative h-32 overflow-hidden">
