          <motion.div {...stag(4)} className="h-fit rounded-[28px] bg-white p-5" style={{ boxShadow: SHADOW }}>
            <div className="flex items-center gap-2"><AlertTriangle size={20} color={C.coral} /><h2 className="text-xl font-extrabold">Needs a cheer</h2></div>
            <p className="text-sm font-bold" style={{ color: C.mute }}>Recent failed quizzes from your students</p>
            <div className="mt-3 flex flex-col gap-2">
              {alerts.length === 0 && <p className="flex items-center gap-2 font-bold" style={{ color: C.mint }}><Check size={18} />Everyone is doing great</p>}
              {alerts.map((a) => {
                const s = students.find((x) => x.id === a.student_id);
                const l = lessons.find((x) => x.id === a.lesson_id);
                return (
                  <div key={a.id} className="flex items-center gap-3 rounded-2xl p-2" style={{ background: "rgba(255,122,89,.1)" }}>
