              <div className="flex items-center"><h2 className="flex-1 text-3xl font-extrabold">New course</h2><button aria-label="Close" onClick={() => setOpen(false)} className="grid h-10 w-10 place-items-center rounded-full" style={{ background: "rgba(42,31,77,.08)" }}><X size={20} /></button></div>
              <div className="mt-4 flex flex-col gap-3">
                <input aria-label="Course title" placeholder="Course title" value={title} onChange={(e) => setTitle(e.target.value)} className={input} style={{ borderColor: "rgba(42,31,77,.12)" }} />
                <textarea aria-label="Summary" placeholder="What will students learn?" rows={3} value={summary} onChange={(e) => setSummary(e.target.value)} className={input} style={{ borderColor: "rgba(42,31,77,.12)" }} />
                <div className="flex flex-wrap gap-2">{cats.map((k) => <button key={k} onClick={() => setCategory(k)} className="rounded-full px-3 py-1.5 text-sm font-extrabold" style={{ background: category === k ? C.sun : "rgba(42,31,77,.07)" }}>{k}</button>)}</div>
                <div className="flex gap-2">{["beginner", "intermediate", "advanced"].map((k) => <button key={k} onClick={() => setLevel(k)} className="flex-1 rounded-full px-3 py-2 text-sm font-extrabold capitalize" style={{ background: level === k ? C.ink : "rgba(42,31,77,.07)", color: level === k ? "#fff" : C.ink }}>{k}</button>)}</div>
                <p className="text-sm font-extrabold" style={{ color: C.mute }}>Pick a cover</p>
                <div className="grid grid-cols-4 gap-2">{covers.map((u) => <button key={u} aria-label="Choose cover" onClick={() => setCover(u)} className="relative aspect-square overflow-hidden rounded-2xl" style={{ boxShadow: (cover || covers[0]) === u ? "0 0 0 4px " + C.sun : "none" }}><img src={u} alt="" className="h-full w-full object-cover" /></button>)}</div>
                {err && <p className="rounded-xl p-3 text-sm font-bold" style={{ background: "rgba(255,122,89,.14)", color: "#D4492A" }}>{err}</p>}
                <motion.button whileTap={{ scale: 0.95 }} disabled={busy} onClick={create} className="mt-1 rounded-full px-6 py-4 text-xl font-extrabold" style={{ background: C.sun, boxShadow: "0 6px 0 #E8940A" }}>{busy ? "Creating…" : "Create course"}</motion.button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

