function Cover({ c, className }: { c: R; className?: string }) {
  const [bad, setBad] = useState(false);
  const k = COV[String(c.category)] || COV.Art;
  if (bad) return <div className={(className || "") + " grid place-items-center text-6xl"} style={{ background: "linear-gradient(135deg," + k.a + "," + k.b + ")" }}>{k.e}</div>;
  return <img src={"https://images.unsplash.com/photo-" + k.u + "?auto=format&fit=crop&w=1400&q=70"} alt={String(c.title)} className={className} onError={() => setBad(true)} />;
}
function Av({ s, cls }: { s: R | undefined; cls: string }) {
  const n = String(s ? s.name : "?");
  const hue = [C.coral, C.grape, C.mint, C.sky, C.sun][n.length % 5];
  return <span className={cls + " grid shrink-0 place-items-center rounded-full font-extrabold text-white"} style={{ background: hue }}>{n.split(" ").map((w) => w[0]).slice(0, 2).join("")}</span>;
}
const C = { bg: "#FFF7E6", ink: "#2A1F4D", mute: "#7B7197", sun: "#FFB020", coral: "#FF7A59", mint: "#1FBF9A", sky: "#3FA7FF", grape: "#8E6CF0" };
const FONT = "'Baloo 2','Nunito',ui-rounded,'SF Pro Rounded',system-ui,sans-serif";
const SHADOW = "0 1px 2px rgba(42,31,77,.06), 0 8px 24px -8px rgba(42,31,77,.14), 0 24px 48px -24px rgba(42,31,77,.12)";
const STATUS: Record<string, { t: string; c: string }> = { enrolled: { t: "Enrolled", c: C.sky }, in_progress: { t: "In progress", c: C.sun }, completed: { t: "Completed", c: C.mint } };

function Ring({ value, size = 52, stroke = 6, color = C.sun }: { value: number; size?: number; stroke?: number; color?: string }) {
  const reduce = useReducedMotion();
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  const v = Math.max(0, Math.min(100, value));
  return (
    <div className="relative shrink-0" style={{ width: size, height: size }}>
      <svg width={size} height={size} className="-rotate-90">
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="rgba(42,31,77,.09)" strokeWidth={stroke} />
        <motion.circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={color} strokeWidth={stroke} strokeLinecap="round" strokeDasharray={c} initial={{ strokeDashoffset: reduce ? c * (1 - v / 100) : c }} animate={{ strokeDashoffset: c * (1 - v / 100) }} transition={{ duration: reduce ? 0 : 1.1, ease: "easeOut" }} />
      </svg>
      <div className="absolute inset-0 grid place-items-center text-xs font-extrabold">{v}%</div>
    </div>
  );
}

export type InstructorCourseProps = { app?: AppHandle };

export default function InstructorCourse({ app }: InstructorCourseProps) {
  const reduce = useReducedMotion();
  const id = app ? app.params.id : "";
  const [tab, setTab] = useState<"lessons" | "students">("lessons");
  const [sheet, setSheet] = useState<null | { kind: "lesson" } | { kind: "question"; lessonId: string }>(null);
  const [f, setF] = useState<Record<string, string>>({ correct: "a" });
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const course = ((app ? app.rows("course") : []) as R[]).find((c) => c.id === id);
  const lessons = ((app ? app.rows("lesson") : []) as R[]).filter((l) => l.course_id === id).sort((a, b) => Number(a.position) - Number(b.position));
  const questions = (app ? app.rows("quiz_question") : []) as R[];
  const enrolls = ((app ? app.rows("enrollment") : []) as R[]).filter((e) => e.course_id === id);
  const attempts = ((app ? app.rows("quiz_attempt") : []) as R[]).filter((a) => a.course_id === id);
  const progress = ((app ? app.rows("lesson_progress") : []) as R[]).filter((p) => p.course_id === id);
  const students = (app ? app.rows("student") : []) as R[];
  const allLessons = (app ? app.rows("lesson") : []) as R[];
  const thumbs = Array.from(new Set(allLessons.map((l) => String(l.thumb)))).slice(0, 6);
  if (!app) return null;
  if (!course) return <div className="grid min-h-screen place-items-center" style={{ background: C.bg }}><div className="h-40 w-72 animate-pulse rounded-[28px]" style={{ background: "rgba(42,31,77,.08)" }} /></div>;
  const meId = app.me("instructor");
  const stag = (i: number) => ({ initial: { opacity: 0, y: reduce ? 0 : 20 }, animate: { opacity: 1, y: 0 }, transition: { delay: reduce ? 0 : 0.05 * i, type: "spring" as const, stiffness: 260, damping: 24 } });
  const set = (k: string, v: string) => setF((p) => ({ ...p, [k]: v }));
  const close = () => { setSheet(null); setErr(null); setF({ correct: "a" }); };

  const save = async () => {
    if (!sheet) return;
    setBusy(true); setErr(null);
    try {
      if (sheet.kind === "lesson") {
        if (!f.title || !f.body) { setErr("Add a title and some lesson text."); setBusy(false); return; }
        await app.create("lesson", { course_id: id, instructor_id: meId, position: lessons.length + 1, title: f.title, body: f.body, thumb: f.thumb || thumbs[0] || String(course.cover), minutes: Number(f.minutes) || 5 });
      } else {
        if (!f.prompt || !f.option_a || !f.option_b) { setErr("Add a question and at least two options."); setBusy(false); return; }
        await app.create("quiz_question", { lesson_id: sheet.lessonId, instructor_id: meId, prompt: f.prompt, option_a: f.option_a, option_b: f.option_b, option_c: f.option_c || "None of these", option_d: f.option_d || "All of these", correct: f.correct || "a", explanation: f.explanation || "" });
      }
      close();
    } catch (e) { setErr(e instanceof Error ? e.message : "Could not save."); }
    setBusy(false);
  };

  const inp = "w-full rounded-2xl border-2 bg-white px-4 py-3 text-base font-bold outline-none focus:border-[#FFB020]";
  const bd = { borderColor: "rgba(42,31,77,.12)" };

  const lessonsPane = (
    <div className={tab === "lessons" ? "block" : "hidden lg:block"}>
      <div className="flex items-center"><h2 className="flex-1 text-2xl font-extrabold">Lessons &amp; quizzes</h2>
        <motion.button whileTap={{ scale: 0.93 }} whileHover={{ scale: 1.04 }} onClick={() => setSheet({ kind: "lesson" })} className="flex items-center gap-1 rounded-full px-4 py-2 text-sm font-extrabold" style={{ background: C.sun, boxShadow: "0 4px 0 #E8940A" }}><Plus size={16} strokeWidth={3} />Add lesson</motion.button></div>
      <div className="mt-3 flex flex-col gap-3">
        {lessons.length === 0 && <div className="rounded-[28px] bg-white p-8 text-center font-bold" style={{ boxShadow: SHADOW, color: C.mute }}>No lessons yet. Add your first one!</div>}
        {lessons.map((l, i) => {
          const qs = questions.filter((q) => q.lesson_id === l.id);
          return (
            <motion.div key={l.id} layout {...stag(i)} className="flex items-center gap-3 rounded-[24px] bg-white p-3" style={{ boxShadow: SHADOW }}>
              <Cover c={course} className="h-16 w-20 shrink-0 rounded-2xl object-cover" />
              <div className="min-w-0 flex-1">
                <p className="text-xs font-extrabold uppercase" style={{ color: C.mute }}>Lesson {i + 1} · {Number(l.minutes)} min</p>
                <h3 className="truncate text-lg font-extrabold leading-tight">{String(l.title)}</h3>
                <p className="flex items-center gap-1 text-xs font-bold" style={{ color: C.grape }}><HelpCircle size={14} />{qs.length} quiz question{qs.length === 1 ? "" : "s"}</p>
              </div>
              <motion.button whileTap={{ scale: 0.92 }} onClick={() => setSheet({ kind: "question", lessonId: String(l.id) })} aria-label="Add question" className="flex items-center gap-1 rounded-full px-3 py-2 text-xs font-extrabold" style={{ background: "rgba(142,108,240,.16)", color: C.grape }}><Plus size={14} strokeWidth={3} />Question</motion.button>
            </motion.div>
          );
        })}
      </div>
    </div>
  );

  const studentsPane = (
    <div className={tab === "students" ? "block" : "hidden lg:block"}>
      <h2 className="text-2xl font-extrabold">Students</h2>
      <div className="mt-3 flex flex-col gap-3">
        {enrolls.length === 0 && <div className="rounded-[28px] bg-white p-8 text-center font-bold" style={{ boxShadow: SHADOW, color: C.mute }}>No students yet.</div>}
        {enrolls.map((e, i) => {
          const s = students.find((x) => x.id === e.student_id);
          const done = progress.filter((p) => p.student_id === e.student_id).length;
          const pct = e.status === "completed" ? 100 : Math.round((done / Math.max(1, lessons.length)) * 100);
          const st = STATUS[String(e.status)] || STATUS.enrolled;
          return (
            <motion.div key={e.id} layout {...stag(i)} className="rounded-[24px] bg-white p-4" style={{ boxShadow: SHADOW }}>
              <div className="flex items-center gap-3">
                {s && <Av s={s} cls="h-12 w-12 text-lg" />}
                <div className="min-w-0 flex-1"><p className="truncate text-lg font-extrabold leading-tight">{s ? String(s.name) : "Student"}</p><span className="rounded-full px-2.5 py-0.5 text-xs font-extrabold text-white" style={{ background: st.c }}>{st.t}</span></div>
                <Ring value={pct} color={st.c} />
              </div>
              <div className="mt-3 flex flex-wrap gap-2">
                {lessons.map((l, li) => {
                  const tries = attempts.filter((a) => a.student_id === e.student_id && a.lesson_id === l.id);
                  const best = tries.reduce<R | null>((m, a) => (!m || Number(a.score) > Number(m.score) ? a : m), null);
                  const ok = tries.some((a) => a.result === "passed");
                  return (
                    <span key={l.id} className="flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-extrabold" style={{ background: !best ? "rgba(42,31,77,.07)" : ok ? "rgba(31,191,154,.16)" : "rgba(255,122,89,.16)", color: !best ? C.mute : ok ? "#0E8F73" : "#D4492A" }}>
                      L{li + 1} {best ? Number(best.score) + "/" + Number(best.total) : "–"}{tries.length > 0 && <span className="opacity-70">· {tries.length}x</span>}
                    </span>
                  );
                })}
              </div>
            </motion.div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen w-full overflow-x-hidden pb-16" style={{ background: C.bg, color: C.ink, fontFamily: FONT }}>
      <style>{"@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;700;800&family=Nunito:wght@500;700;800&display=swap');"}</style>
      <div className="mx-auto max-w-6xl lg:px-8 lg:pt-6">
        <div className="relative h-52 overflow-hidden lg:h-60 lg:rounded-[36px]" style={{ boxShadow: SHADOW }}>
          <Cover c={course} className="h-full w-full object-cover" />
          <div className="absolute inset-0" style={{ background: "linear-gradient(180deg,rgba(42,31,77,.3),rgba(42,31,77,.8))" }} />
          <motion.button whileTap={{ scale: 0.88 }} onClick={() => app.navigate("/teach")} aria-label="Back" className="absolute left-4 top-4 grid h-11 w-11 place-items-center rounded-full bg-white"><ArrowLeft size={22} /></motion.button>
          <div className="absolute inset-x-0 bottom-0 p-5 text-white lg:p-8">
            <p className="text-sm font-extrabold uppercase tracking-wide opacity-80">{String(course.category)} · {String(course.level)}</p>
            <h1 className="text-4xl font-extrabold leading-none lg:text-5xl">{String(course.title)}</h1>
            <p className="mt-1 text-sm font-bold opacity-90">{lessons.length} lessons · {enrolls.length} students · {enrolls.filter((e) => e.status === "completed").length} finished</p>
          </div>
        </div>

        <div className="relative mx-4 mt-4 flex rounded-full p-1 lg:hidden" style={{ background: "rgba(42,31,77,.07)" }}>
          {([{ k: "lessons", t: "Lessons", I: Book }, { k: "students", t: "Students", I: Users }] as const).map((x) => (
            <button key={x.k} onClick={() => setTab(x.k)} className="relative flex flex-1 items-center justify-center gap-1.5 rounded-full py-2 text-base font-extrabold" style={{ color: tab === x.k ? C.ink : C.mute }}>
              {tab === x.k && <motion.span layoutId="ic-tab" className="absolute inset-0 rounded-full bg-white" style={{ boxShadow: SHADOW }} transition={{ type: "spring", stiffness: 420, damping: 32 }} />}
              <span className="relative flex items-center gap-1.5"><x.I size={18} />{x.t}</span>
            </button>
          ))}
        </div>

        <div className="mt-6 grid gap-8 px-4 lg:grid-cols-2 lg:px-0">{lessonsPane}{studentsPane}</div>
      </div>

      <AnimatePresence>
        {sheet && (
          <motion.div key="scrim" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={close} className="fixed inset-0 z-40 flex items-end justify-center lg:items-center" style={{ background: "rgba(42,31,77,.6)" }}>
            <motion.div initial={{ y: 80, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 80, opacity: 0 }} transition={{ type: "spring", stiffness: 300, damping: 28 }} onClick={(e) => e.stopPropagation()} className="max-h-[92vh] w-full max-w-lg overflow-y-auto rounded-t-[36px] bg-white p-6 lg:rounded-[36px]">
              <div className="flex items-center"><h2 className="flex-1 text-3xl font-extrabold">{sheet.kind === "lesson" ? "New lesson" : "New quiz question"}</h2><button aria-label="Close" onClick={close} className="grid h-10 w-10 place-items-center rounded-full" style={{ background: "rgba(42,31,77,.08)" }}><X size={20} /></button></div>
              <div className="mt-4 flex flex-col gap-3">
                {sheet.kind === "lesson" ? (
                  <>
                    <input aria-label="Lesson title" placeholder="Lesson title" value={f.title || ""} onChange={(e) => set("title", e.target.value)} className={inp} style={bd} />
                    <textarea aria-label="Lesson text" placeholder="Write the lesson…" rows={5} value={f.body || ""} onChange={(e) => set("body", e.target.value)} className={inp} style={bd} />
                    <input aria-label="Minutes" type="number" placeholder="Minutes" value={f.minutes || ""} onChange={(e) => set("minutes", e.target.value)} className={inp} style={bd} />
                    <p className="text-sm font-extrabold" style={{ color: C.mute }}>Video thumbnail</p>
                    <div className="grid grid-cols-3 gap-2">{thumbs.map((u) => <button key={u} aria-label="Choose thumbnail" onClick={() => set("thumb", u)} className="aspect-video overflow-hidden rounded-2xl" style={{ boxShadow: (f.thumb || thumbs[0]) === u ? "0 0 0 4px " + C.sun : "none" }}><img src={u} alt="" className="h-full w-full object-cover" /></button>)}</div>
                  </>
                ) : (
                  <>
                    <textarea aria-label="Question" placeholder="Question" rows={2} value={f.prompt || ""} onChange={(e) => set("prompt", e.target.value)} className={inp} style={bd} />
                    {["a", "b", "c", "d"].map((L) => (
                      <div key={L} className="flex items-center gap-2">
                        <button aria-label={"Mark " + L + " correct"} onClick={() => set("correct", L)} className="grid h-11 w-11 shrink-0 place-items-center rounded-xl text-base font-extrabold uppercase" style={{ background: f.correct === L ? C.mint : "rgba(42,31,77,.08)", color: f.correct === L ? "#fff" : C.ink }}>{f.correct === L ? <Check size={20} strokeWidth={3} /> : L}</button>
                        <input aria-label={"Option " + L} placeholder={"Option " + L.toUpperCase()} value={f["option_" + L] || ""} onChange={(e) => set("option_" + L, e.target.value)} className={inp} style={bd} />
                      </div>
                    ))}
                    <p className="text-xs font-bold" style={{ color: C.mute }}>Tap a letter to mark the correct answer.</p>
                    <input aria-label="Explanation" placeholder="Explanation (optional)" value={f.explanation || ""} onChange={(e) => set("explanation", e.target.value)} className={inp} style={bd} />
                  </>
                )}
                {err && <p className="rounded-xl p-3 text-sm font-bold" style={{ background: "rgba(255,122,89,.14)", color: "#D4492A" }}>{err}</p>}
                <motion.button whileTap={{ scale: 0.95 }} disabled={busy} onClick={save} className="rounded-full px-6 py-4 text-xl font-extrabold" style={{ background: C.sun, boxShadow: "0 6px 0 #E8940A" }}>{busy ? "Saving…" : "Save"}</motion.button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
